sksl:
uniform shader image;
uniform float2 size;
uniform float time;
layout(color) uniform half4 color1;
uniform float2 point1;
layout(color) uniform half4 color2;
uniform float2 point2;
layout(color) uniform half4 color3;
uniform float2 point3;
layout(color) uniform half4 color4;
uniform float2 point4;
uniform float softness;
uniform float opacity;
uniform float blend;
uniform float corner;
uniform float falloff;
uniform float style;
float3 blendWith(float m, float3 b, float3 s) {
    if (m < 0.5) return s;
    if (m < 1.5) return b * s;
    if (m < 2.5) return b + s - b * s;
    if (m < 3.5) return mix(2.0 * b * s, 1.0 - 2.0 * (1.0 - b) * (1.0 - s), step(0.5, b));
    if (m < 4.5) {
        float3 d = mix(sqrt(b), ((16.0 * b - 12.0) * b + 4.0) * b, step(b, float3(0.25)));
        return mix(b - (1.0 - 2.0 * s) * b * (1.0 - b), b + (2.0 * s - 1.0) * (d - b), step(0.5, s));
    }
    if (m < 5.5) return mix(2.0 * b * s, 1.0 - 2.0 * (1.0 - b) * (1.0 - s), step(0.5, s));
    if (m < 6.5) return min(b + s, 1.0);
    if (m < 7.5) return min(b, s);
    if (m < 8.5) return max(b, s);
    if (m < 9.5) return abs(b - s);
    if (m < 10.5) return min(b / max(1.0 - s, 0.0001), 1.0);
    return 1.0 - min((1.0 - b) / max(s, 0.0001), 1.0);
}
half4 main(float2 coord) {
    half4 c = image.eval(coord);
    if (c.a <= 0.0) return c;
    float3 base = float3(c.rgb) / float(c.a);
    float2 p = coord - 0.5 * size;
    float unit = max(max(size.x, size.y), 1.0);
    float2 reach = 0.5 * size * corner;
    float2 q1 = point1 + float2(-reach.x, -reach.y);
    float2 q2 = point2 + float2(reach.x, -reach.y);
    float2 q3 = point3 + float2(reach.x, reach.y);
    float2 q4 = point4 + float2(-reach.x, reach.y);
    float power = 2.0 + 6.0 * (1.0 - clamp(softness, 0.0, 1.0));
    float w1 = pow(max(distance(p, q1) / unit, 0.001), -power);
    float w2 = pow(max(distance(p, q2) / unit, 0.001), -power);
    float w3 = pow(max(distance(p, q3) / unit, 0.001), -power);
    float w4 = pow(max(distance(p, q4) / unit, 0.001), -power);
    float4 g = (w1 * float4(color1) + w2 * float4(color2) + w3 * float4(color3) + w4 * float4(color4)) / (w1 + w2 + w3 + w4);
    if (falloff > 0.5) {
        float2 n = max(size, float2(1.0));
        float r = max(softness, 0.01);
        float s1 = 1.0 - smoothstep(0.0, r, length((p - q1) / n));
        float s2 = 1.0 - smoothstep(0.0, r, length((p - q2) / n));
        float s3 = 1.0 - smoothstep(0.0, r, length((p - q3) / n));
        float s4 = 1.0 - smoothstep(0.0, r, length((p - q4) / n));
        g = (s1 * float4(color1) + s2 * float4(color2) + s3 * float4(color3) + s4 * float4(color4) + 0.0001 * g) / (s1 + s2 + s3 + s4 + 0.0001);
    }
    if (style > 0.5) {
        float2 uv = coord / max(size, float2(1.0));
        float k = max(2.59 / max(softness, 0.001) - 0.36, 0.01);
        float2 e1 = uv - float2(point1.x / 500.0, 1.0 + point1.y / 500.0);
        float2 e2 = uv - float2(point2.x / 500.0, 1.0 + point2.y / 500.0);
        float2 e3 = uv - float2(point3.x / 500.0, 1.0 + point3.y / 500.0);
        float2 e4 = uv - float2(point4.x / 500.0, 1.0 + point4.y / 500.0);
        float4 dd = float4(dot(e1, e1), dot(e2, e2), dot(e3, e3), dot(e4, e4));
        float4 q = clamp(1.0 - dd, 0.0, 1.0);
        float top = max(max(q.x, q.y), max(q.z, q.w));
        float3 mixed = float3(0.0);
        if (top > 0.0) {
            float4 r = q / top;
            float4 w = pow(r, float4(k));
            float4 w1 = pow(r, float4(2.23));
            float3 sum = w.x * float3(color1.rgb) * float(color1.a) + w.y * float3(color2.rgb) * float(color2.a)
                + w.z * float3(color3.rgb) * float(color3.a) + w.w * float3(color4.rgb) * float(color4.a);
            mixed = clamp(sum / (w1.x + w1.y + w1.z + w1.w) * pow(top, k - 2.23), 0.0, 1.0);
            float2 near = top == q.x ? e1 : top == q.y ? e2 : top == q.z ? e3 : e4;
            float dn = max(length(near), 0.000001);
            float slope = dn / max(length(near / max(size, float2(1.0))), 0.000001);
            mixed *= clamp((1.0 - dn) * slope + 0.5, 0.0, 1.0);
        }
        g = float4(mixed, 1.0);
    }
    float3 rgb = mix(base, clamp(blendWith(blend, base, g.rgb), 0.0, 1.0), clamp(opacity, 0.0, 1.0) * g.a);
    return half4(half3(clamp(rgb, 0.0, 1.0)) * c.a, c.a);
}
